                                <h3 className="text-xl font-semibold text-center text-teal-200">
                                    {line.content}
                                </h3>
                            </div>
                        );
                    }

                    const isVerse = line.type === 'verse';
                    const textAlign = mode === 'song' ? 'text-center' : (isRtl ? 'text-right' : 'text-left');

                    return (
